import java.util.*;

class Solution {
    public int[][] paintBucket(int[][] image, int row, int col, int color) {
        int old = image[row][col];
        if (old == color) return image; // nothing changes, and avoids an endless loop
        int r = image.length, c = image[0].length;
        int[][] dirs = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};
        ArrayDeque<int[]> stack = new ArrayDeque<>();
        image[row][col] = color;
        stack.push(new int[]{row, col});
        while (!stack.isEmpty()) {
            int[] cur = stack.pop();
            for (int[] d : dirs) {
                int x = cur[0] + d[0], y = cur[1] + d[1];
                if (x >= 0 && y >= 0 && x < r && y < c && image[x][y] == old) {
                    image[x][y] = color; // recolour = visited
                    stack.push(new int[]{x, y});
                }
            }
        }
        return image;
    }
}

