class Solution:
    def paintBucket(self, image: List[List[int]], row: int, col: int, color: int) -> List[List[int]]:
        old = image[row][col]
        if old == color: return image
        r, c = len(image), len(image[0]); st = [(row, col)]; image[row][col] = color
        while st:
            i, j = st.pop()
            for x, y in ((i+1,j),(i-1,j),(i,j+1),(i,j-1)):
                if 0 <= x < r and 0 <= y < c and image[x][y] == old:
                    image[x][y] = color; st.append((x, y))
        return image

