function paintBucket(image, row, col, color) {
  const old = image[row][col]; if (old === color) return image;
  const r = image.length, c = image[0].length, st = [[row, col]]; image[row][col] = color;
  while (st.length) {
    const [i, j] = st.pop();
    for (const [x, y] of [[i+1,j],[i-1,j],[i,j+1],[i,j-1]])
      if (x >= 0 && x < r && y >= 0 && y < c && image[x][y] === old) { image[x][y] = color; st.push([x, y]); }
  }
  return image;
}
